from __future__ import annotations

import ast
from pathlib import Path
from typing import Any


def _extract_stmt_name(node: ast.stmt) -> str | None:
    """Return the symbol name defined by an AST statement (function, class, Assign, or AnnAssign)."""
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        return node.name
    if isinstance(node, ast.Assign):
        for target in node.targets:
            if isinstance(target, ast.Name):
                return target.id
    if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        return node.target.id
    return None


def edit_ast_node(
    file_path: str | Path,
    target_name: str,
    new_code: str,
) -> dict[str, Any]:
    """Replace or append a function/class/assignment AST node in a .py file with built-in syntax GUARD."""
    path = Path(file_path)

    # 1. Syntax GUARD on incoming snippet
    try:
        snippet_tree = ast.parse(new_code)
    except SyntaxError as exc:
        return {
            "status": "error",
            "guard": "SYNTAX_GUARD_REJECTED",
            "file": str(path),
            "target_name": target_name,
            "error": f"SyntaxError in new_code: {exc}",
        }

    if not snippet_tree.body:
        return {
            "status": "error",
            "guard": "SYNTAX_GUARD_REJECTED",
            "file": str(path),
            "target_name": target_name,
            "error": "Provided new_code contains no AST statements.",
        }

    # Find the primary statement matching target_name if multiple statements (e.g. imports + def) were provided
    matching_stmt = None
    extra_imports: list[ast.stmt] = []
    for stmt in snippet_tree.body:
        if _extract_stmt_name(stmt) == target_name and matching_stmt is None:
            matching_stmt = stmt
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            extra_imports.append(stmt)

    new_node = matching_stmt if matching_stmt is not None else snippet_tree.body[-1]

    if path.exists():
        existing_source = path.read_text(encoding="utf-8")
        try:
            tree = ast.parse(existing_source)
        except SyntaxError as exc:
            return {
                "status": "error",
                "guard": "SYNTAX_GUARD_REJECTED",
                "file": str(path),
                "target_name": target_name,
                "error": f"Existing file has SyntaxError: {exc}",
            }
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        tree = ast.Module(body=[], type_ignores=[])

    existing_import_dumps = {
        ast.dump(node) for node in tree.body if isinstance(node, (ast.Import, ast.ImportFrom))
    }
    deduped_imports = [imp for imp in extra_imports if ast.dump(imp) not in existing_import_dumps]

    replaced = False
    new_body: list[ast.stmt] = list(deduped_imports)
    for node in tree.body:
        node_name = _extract_stmt_name(node)
        if node_name == target_name and not replaced:
            new_body.append(new_node)
            replaced = True
        else:
            new_body.append(node)

    if not replaced:
        new_body.append(new_node)

    tree.body = new_body
    ast.fix_missing_locations(tree)
    rendered_code = ast.unparse(tree) + "\n"

    # 2. Final full-file Syntax GUARD before writing to disk
    try:
        ast.parse(rendered_code)
    except SyntaxError as exc:
        return {
            "status": "error",
            "guard": "SYNTAX_GUARD_REJECTED",
            "file": str(path),
            "target_name": target_name,
            "error": f"Rendered file failed SyntaxError guard: {exc}",
        }

    path.write_text(rendered_code, encoding="utf-8")
    return {
        "status": "ok",
        "guard": "SYNTAX_GUARD_PASSED",
        "file": str(path),
        "target_name": target_name,
        "action": "replaced" if replaced else "appended",
    }

from __future__ import annotations

import re
from pathlib import Path
from typing import Any


def _strip_duplicate_leading_heading(content: str, section_title: str) -> str:
    """Remove a leading Markdown or LaTeX section heading if it duplicates section_title."""
    cleaned = content.strip()
    md_prefix = re.compile(rf"^##+\s+{re.escape(section_title)}\s*\n+", re.IGNORECASE)
    tex_prefix = re.compile(rf"^\\(?:sub)*section\{{{re.escape(section_title)}\}}\s*\n+", re.IGNORECASE)
    cleaned = md_prefix.sub("", cleaned, count=1)
    cleaned = tex_prefix.sub("", cleaned, count=1)
    return cleaned.strip()


def edit_document_section(
    file_path: str | Path,
    section_title: str,
    new_content: str,
) -> dict[str, Any]:
    """Edit a single subsection in a .md or .tex file without overwriting the rest of the document."""
    path = Path(file_path)
    suffix = path.suffix.lower()
    if suffix not in (".md", ".tex"):
        return {
            "status": "error",
            "file": str(path),
            "error": f"Unsupported document format '{suffix}'. Expected .md or .tex.",
        }

    normalized_body = _strip_duplicate_leading_heading(new_content, section_title)

    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        if suffix == ".tex":
            initial = f"\\subsection{{{section_title}}}\n{normalized_body}\n"
        else:
            initial = f"## {section_title}\n{normalized_body}\n"
        path.write_text(initial, encoding="utf-8")
        return {
            "status": "ok",
            "file": str(path),
            "section_title": section_title,
            "action": "created",
        }

    existing = path.read_text(encoding="utf-8")

    if suffix == ".md":
        pattern = re.compile(
            rf"(^##+\s+{re.escape(section_title)}\s*$)(.*?)(?=^##+\s+|\Z)",
            re.MULTILINE | re.DOTALL,
        )
        if pattern.search(existing):
            updated = pattern.sub(
                lambda m: f"{m.group(1)}\n{normalized_body}\n\n",
                existing,
                count=1,
            )
            action = "replaced"
        else:
            sep = "\n" if existing.endswith("\n") else "\n\n"
            updated = f"{existing}{sep}## {section_title}\n{normalized_body}\n"
            action = "appended"
    else:
        pattern = re.compile(
            rf"(\\(?:sub)*section\{{{re.escape(section_title)}\}})(.*?)(?=\\(?:sub)*section\{{|\Z)",
            re.DOTALL,
        )
        if pattern.search(existing):
            updated = pattern.sub(
                lambda m: f"{m.group(1)}\n{normalized_body}\n\n",
                existing,
                count=1,
            )
            action = "replaced"
        else:
            sep = "\n" if existing.endswith("\n") else "\n\n"
            updated = f"{existing}{sep}\\subsection{{{section_title}}}\n{normalized_body}\n"
            action = "appended"

    path.write_text(updated, encoding="utf-8")
    return {
        "status": "ok",
        "file": str(path),
        "section_title": section_title,
        "action": action,
    }

from __future__ import annotations

import ast
import re
from pathlib import Path
from typing import Any

from adk.core.models import read_json_state, resolve_adk_path, write_json_state


def sync_hypergraph_matrix(
    workspace_dir: str | Path = "workspace",
    matrix_path: str | Path = "state/hypergraph_matrix.json",
) -> dict[str, Any]:
    """Scan .py imports and \\ref_ast / \\ref_csv tags in workspace/ and update hypergraph_matrix.json."""
    w_dir = resolve_adk_path(workspace_dir)
    data = read_json_state(matrix_path)
    nodes: dict[str, dict[str, Any]] = data.get("nodes", {})
    edges: dict[str, list[str]] = data.get("edges", {})
    matrix: dict[str, dict[str, int]] = data.get("matrix", {})

    path_to_node: dict[str, str] = {}
    stem_to_node: dict[str, str] = {}
    for node_id, meta in nodes.items():
        rel_path = meta.get("path", "")
        if rel_path:
            path_to_node[rel_path] = node_id
            stem_to_node[Path(rel_path).stem] = node_id

    if w_dir.exists():
        for file_path in sorted(w_dir.rglob("*")):
            if not file_path.is_file() or file_path.name == ".gitkeep" or "__pycache__" in file_path.parts:
                continue
            rel = file_path.relative_to(w_dir).as_posix()
            if rel not in path_to_node:
                new_id = f"v{len(nodes) + 1}"
                nodes[new_id] = {"path": rel, "degree": 0, "weight": 1.0}
                matrix[new_id] = {e_id: 0 for e_id in edges}
                path_to_node[rel] = new_id
                stem_to_node[file_path.stem] = new_id

    dynamic_couplings: list[tuple[str, str]] = []
    for rel_path, src_node in list(path_to_node.items()):
        full_path = w_dir / rel_path
        if not full_path.exists():
            continue

        content = full_path.read_text(encoding="utf-8", errors="ignore")
        if rel_path.endswith(".py"):
            try:
                tree = ast.parse(content)
                for stmt in ast.walk(tree):
                    if isinstance(stmt, ast.Import):
                        for alias in stmt.names:
                            mod_stem = alias.name.split(".")[-1]
                            if mod_stem in stem_to_node and stem_to_node[mod_stem] != src_node:
                                dynamic_couplings.append((src_node, stem_to_node[mod_stem]))
                    elif isinstance(stmt, ast.ImportFrom) and stmt.module:
                        mod_stem = stmt.module.split(".")[-1]
                        if mod_stem in stem_to_node and stem_to_node[mod_stem] != src_node:
                            dynamic_couplings.append((src_node, stem_to_node[mod_stem]))
            except SyntaxError:
                pass
        elif rel_path.endswith((".md", ".tex")):
            for match in re.finditer(r"\\ref_(?:ast|csv)\{([^:}]+):([^}]+)\}", content):
                ref_file = match.group(1).strip()
                target_node = path_to_node.get(ref_file) or stem_to_node.get(Path(ref_file).stem)
                if target_node and target_node != src_node:
                    dynamic_couplings.append((src_node, target_node))
            for match in re.finditer(r"\\ref_fig\{([^}]+)\}", content):
                fig_file = match.group(1).strip()
                target_node = path_to_node.get(fig_file) or stem_to_node.get(Path(fig_file).stem)
                if target_node and target_node != src_node:
                    dynamic_couplings.append((src_node, target_node))
            for match in re.finditer(r"\\includegraphics(?:\[[^\]]*\])?\{([^}]+)\}", content):

                gfx_path = match.group(1).strip()
                target_node = path_to_node.get(gfx_path) or stem_to_node.get(Path(gfx_path).stem)
                if target_node and target_node != src_node:
                    dynamic_couplings.append((src_node, target_node))
            if re.search(r"\\cite\{([^}]+)\}", content):
                for bib_rel, bib_node in path_to_node.items():
                    if bib_rel.endswith(".bib") and bib_node != src_node:
                        dynamic_couplings.append((src_node, bib_node))

    for node_a, node_b in dynamic_couplings:
        pair_set = {node_a, node_b}
        matched_edge = None
        for edge_id, members in edges.items():
            if pair_set.issubset(set(members)):
                matched_edge = edge_id
                break
        if matched_edge is None:
            matched_edge = f"E{len(edges) + 1}"
            edges[matched_edge] = sorted(pair_set)
            for n_id in nodes:
                matrix.setdefault(n_id, {})[matched_edge] = 1 if n_id in pair_set else 0

    all_edge_ids = list(edges.keys())
    for n_id in nodes:
        row = matrix.setdefault(n_id, {})
        for e_id in all_edge_ids:
            row[e_id] = 1 if n_id in edges[e_id] else int(row.get(e_id, 0))
            if row[e_id] == 1 and n_id not in edges[e_id]:
                edges[e_id].append(n_id)
        degree = sum(int(v) for v in row.values())
        nodes[n_id]["degree"] = degree

    write_json_state(
        matrix_path,
        {
            "nodes": nodes,
            "edges": edges,
            "matrix": matrix,
        },
    )
    return {
        "status": "ok",
        "nodes_count": len(nodes),
        "edges_count": len(edges),
        "degrees": {n_id: meta["degree"] for n_id, meta in nodes.items()},
    }

from __future__ import annotations

import ast
import csv
from pathlib import Path
from typing import Any

from adk.core.models import read_json_state, resolve_adk_path


def extract_hyperedge_exports(
    edge_id: str = "E1",
    matrix_path: str | Path = "state/hypergraph_matrix.json",
    workspace_dir: str | Path = "workspace",
    node_id: str | None = None,
) -> dict[str, Any]:
    """Extract exported AST symbols for .py files and CSV column/row schemas across hyperedges."""
    w_dir = resolve_adk_path(workspace_dir)
    data = read_json_state(matrix_path)
    nodes: dict[str, Any] = data.get("nodes", {})
    edges: dict[str, list[str]] = data.get("edges", {})
    matrix: dict[str, dict[str, int]] = data.get("matrix", {})

    if node_id and node_id in matrix:
        active_edges = [e_id for e_id, val in matrix[node_id].items() if int(val) == 1]
        if "E1" in edges and "E1" not in active_edges:
            active_edges.append("E1")
        target_node_ids: list[str] = []
        for e_id in active_edges:
            for n_id in edges.get(e_id, []):
                if n_id not in target_node_ids:
                    target_node_ids.append(n_id)
    elif edge_id == "ALL":
        target_node_ids = list(nodes.keys())
    else:
        target_node_ids = list(edges.get(edge_id, []))

    exports_by_file: dict[str, dict[str, list[str]]] = {}
    csv_schemas: dict[str, dict[str, list[str]]] = {}

    for n_id in target_node_ids:
        rel_path = nodes.get(n_id, {}).get("path", "")
        if rel_path.endswith(".py"):
            py_file = w_dir / rel_path
            if not py_file.exists():
                exports_by_file[rel_path] = {"functions": [], "classes": [], "variables": []}
                continue

            try:
                tree = ast.parse(py_file.read_text(encoding="utf-8"))
            except SyntaxError:
                exports_by_file[rel_path] = {"functions": [], "classes": [], "variables": []}
                continue

            functions: list[str] = []
            classes: list[str] = []
            variables: list[str] = []

            for node in tree.body:
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
                    functions.append(node.name)
                elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
                    classes.append(node.name)
                elif isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and not target.id.startswith("_"):
                            variables.append(target.id)
                elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                    if not node.target.id.startswith("_"):
                        variables.append(node.target.id)

            exports_by_file[rel_path] = {
                "functions": functions,
                "classes": classes,
                "variables": variables,
            }
        elif rel_path.endswith(".csv"):
            csv_file = w_dir / rel_path
            if csv_file.exists():
                with csv_file.open("r", encoding="utf-8", newline="") as f:
                    reader = list(csv.DictReader(f))
                    cols = list(reader[0].keys()) if reader else []
                    first_col = cols[0] if cols else None
                    row_keys = (
                        [str(r[first_col]) for r in reader if first_col and r.get(first_col)]
                        if first_col
                        else []
                    )
                    csv_schemas[rel_path] = {
                        "columns": cols,
                        "row_selectors": row_keys,
                    }

    return {
        "status": "ok",
        "edge_id": edge_id,
        "exports": exports_by_file,
        "csv_schemas": csv_schemas,
    }

